using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using System.Text.RegularExpressions;
using TownOfHost.Development;
partial class Program {
 static string Fixture([CallerFilePath]string file="")=>Path.Combine(Path.GetDirectoryName(file),"RecordedExitStages.json");
 static ExitStage Stage(string name){Check(Enum.TryParse<ExitStage>(name,out var stage),"missing stage "+name);return stage;}
 static void RunTitleFrameTests(){
 Test("preserved real exit sequence does not imply a successful first menu frame",()=>{using var record=JsonDocument.Parse(File.ReadAllText(Fixture()));var lines=new List<string>();var trace=new SessionExitTrace(lines.Add,()=>1263);trace.Begin(0);foreach(var item in record.RootElement.GetProperty("stages").EnumerateArray())trace.Emit(Stage(item.GetString()));Check(lines.Count==16&&trace.Active);Check(lines.Last().Contains("stage=MenuStartReturned")&&!lines.Any(x=>x.Contains("TrackingComplete")));});
 foreach(var step in new[]{"VersionStart","VersionTemplate","VersionCredentials","VersionErrorText","VersionSupportCheck","VersionEventText","VersionStatistics","VersionStreamText","ModTasks","ModMurder","ModStamp","HeaderLayout"})Test("failed observed step keeps its unmatched boundary: "+step,()=>{
  var lines=new List<string>();var trace=new SessionExitTrace(lines.Add,()=>1);trace.Begin(0);trace.Emit(Stage(step+"Started"));var error=new ObjectDisposedException("synthetic-private-value");trace.Emit(ExitStage.LifecycleException,error);Check(trace.Active&&lines.Any(x=>x.Contains(step+"Started"))&&!lines.Any(x=>x.Contains(step+"Returned"))&&lines.All(x=>!x.Contains("synthetic-private-value")));
 });
 Test("all title-return stages fit the bounded trace without losing its ending",()=>{var lines=new List<string>();var trace=new SessionExitTrace(lines.Add,()=>0);trace.Begin(0);foreach(var stage in Enum.GetValues<ExitStage>())trace.Emit(stage);Check(Enum.GetValues<ExitStage>().Length>24&&lines.Count==Enum.GetValues<ExitStage>().Length&&lines.Count<=SessionExitTrace.MaximumLines&&SessionExitTrace.MaximumLines<=64);});
 foreach(string patch in new[]{"VersionPatch","ModTickPatch"})Test("new native adapters preserve the original exception: "+patch,()=>{var type=typeof(SessionExitDiagnostics).GetNestedType(patch,BindingFlags.NonPublic);Check(type!=null);var error=new InvalidOperationException("synthetic-private-value");Check(ReferenceEquals(Invoke(patch,"Finalizer",error),error));Check(Invoke(patch,"Finalizer",new object[]{null})==null);});
 Test("new first-frame prefix and postfix have distinct observations",()=>{Check(typeof(SessionExitDiagnostics).GetNestedType("MenuTickPatch",BindingFlags.NonPublic).GetMethod("Prefix",BindingFlags.Static|BindingFlags.NonPublic)!=null);Stage("MenuTickStarted");Stage("VersionStartReturned");Stage("ModTickReturned");});
 Test("all Credentials probes are compile-time excluded from public Release",()=>{var source=File.ReadAllText(Path.Combine(Root(),"Patches/CredentialsPatch.cs"));Check(source.Contains("SessionExitDiagnostics.Mark"));var release=Regex.Replace(source,@"(?ms)^#if SHELL_DEBUG_CONTROLLER\r?\n.*?^#endif[^\r\n]*","");Check(!release.Contains("SessionExitDiagnostics")&&!release.Contains("Development.ExitStage"));});
 foreach(var item in new[]{("VersionTemplate","TMPTemplate.SetBase(__instance.text);"),("VersionCredentials","                CreateText();"),("VersionErrorText","ErrorText.Create(__instance.text);"),("VersionSupportCheck","VersionChecker.Check();"),("VersionStatistics","MainMenuManagerPatch.Statistics_TMP = TMPTemplate.Create("),("VersionStreamText","CreateStreameMenu.CreateText();"),("ModTasks","LateTask.Update(Time.deltaTime);"),("ModMurder","CheckMurderPatch.Update();")})Test("production operation stays between its observed boundaries: "+item.Item1,()=>{var source=File.ReadAllText(Path.Combine(Root(),"Patches/CredentialsPatch.cs"));int begin=source.IndexOf("ExitStage."+item.Item1+"Started",StringComparison.Ordinal),operation=source.IndexOf(item.Item2,StringComparison.Ordinal),end=source.IndexOf("ExitStage."+item.Item1+"Returned",StringComparison.Ordinal);Check(begin>=0&&begin<operation&&operation<end);});
 Test("probe revision distinguishes the finer trace from the deployed coarse trace",()=>{var field=typeof(SessionExitDiagnostics).GetField("ProbeRevision",BindingFlags.Static|BindingFlags.NonPublic);Check(field?.GetRawConstantValue() as string=="title-frame-v2");});
 Test("repeated version starts remain visible without per-frame log flooding",()=>{var lines=new List<string>();var trace=new SessionExitTrace(lines.Add,()=>0);trace.Begin(0);for(int i=0;i<10000;i++)trace.Emit(Stage("VersionStartStarted"));Check(lines.Count==3&&lines.Last().Contains("repeat=2plus"));});
 Test("all repeat-sensitive entry points expose one repeated observation each",()=>{var lines=new List<string>();var trace=new SessionExitTrace(lines.Add,()=>0);trace.Begin(0);var stages=new[]{"ExitCallObserved","DisconnectStarted","ObjectsResetStarted","CommentsStopStarted","RolesDisposeStarted","HudDestroyStarted","VersionStartStarted"};foreach(var name in stages)for(int n=0;n<100;n++)trace.Emit(Stage(name));Check(lines.Count==1+2*stages.Length&&lines.Count(x=>x.Contains("repeat=2plus"))==stages.Length);});
 Test("a nested disconnect observation is not mislabelled as a second ExitGame call",()=>{var lines=new List<string>();var trace=new SessionExitTrace(lines.Add,()=>0);trace.Begin(0);trace.Emit(Stage("ExitCallObserved"));trace.Begin(0);trace.Emit(ExitStage.DisconnectStarted);Check(trace.Sequence==1&&!lines.Any(x=>x.Contains("repeat=2plus")));});
 }
}
